import { ok, fail } from './result.js';
import { getCustomer } from './customers.js';
import { getProduct } from './catalogue.js';
import { roundCents } from './money.js';
import { nextInvoiceNumber } from './numbering.js';

/**
 * Validate that a date string is in YYYY-MM-DD format and represents a valid date.
 * @param {string} dateStr
 * @returns {boolean}
 */
function isValidDate(dateStr) {
  const match = /^\d{4}-\d{2}-\d{2}$/.test(dateStr);
  if (!match) return false;
  const date = new Date(dateStr + 'T00:00:00Z');
  return date instanceof Date && !isNaN(date) && date.toISOString().startsWith(dateStr);
}

/**
 * Validate that a discount percent is a number between 0 and 100.
 * @param {any} discountPercent
 * @returns {boolean}
 */
function isValidDiscountPercent(discountPercent) {
  return typeof discountPercent === 'number' && discountPercent >= 0 && discountPercent <= 100;
}

/**
 * Create a new invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }> }} params
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  // Validate customer exists
  const customerResult = getCustomer(customerId);
  if (!customerResult.ok) return customerResult;

  // Validate issueDate
  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  // Validate lines is not empty
  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  // Validate and build invoice lines
  const invoiceLines = [];
  for (const line of lines) {
    // Validate qty is a positive integer
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    // Validate discount percent if provided
    if (line.discountPercent !== undefined && !isValidDiscountPercent(line.discountPercent)) {
      return fail('DISCOUNT_INVALID');
    }

    // Validate SKU exists and get product details
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    const newLine = {
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    };

    if (line.discountPercent !== undefined) {
      newLine.discountPercent = line.discountPercent;
    }

    invoiceLines.push(newLine);
  }

  const invoice = {
    customerId,
    issueDate,
    status: 'draft',
    lines: invoiceLines,
  };

  return ok(invoice);
}

/**
 * Calculate the total for a single line item (qty × unitPrice, rounded to cents).
 * @param {{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent?: number }} line
 * @returns {number}
 */
export function lineTotal(line) {
  return roundCents(line.qty * line.unitPrice);
}

/**
 * Calculate the discount amount for a single line item.
 * @param {{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent?: number }} line
 * @returns {number}
 */
export function lineDiscount(line) {
  if (line.discountPercent === undefined) return 0;
  const total = lineTotal(line);
  const discount = roundCents(total * line.discountPercent / 100);
  return Math.max(0, discount);
}

/**
 * Calculate totals for an invoice.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @returns {{ subtotal: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  return {
    subtotal,
    total: subtotal,
  };
}

/**
 * Add or increase a line on an invoice.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {{ sku: string, qty: number }} params
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty }) {
  // Check status is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Validate qty is a positive integer
  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  // Validate SKU exists and get product details
  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;
  const newLines = invoice.lines.map((line) => ({ ...line }));

  // Check if SKU already exists
  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);
  if (existingLineIndex >= 0) {
    // Increase qty on existing line
    newLines[existingLineIndex] = {
      ...newLines[existingLineIndex],
      qty: newLines[existingLineIndex].qty + qty,
    };
  } else {
    // Add new line
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    });
  }

  const newInvoice = {
    ...invoice,
    lines: newLines,
  };

  return ok(newInvoice);
}

/**
 * Remove a line from an invoice.
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  // Check status is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Check if SKU exists on invoice
  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex < 0) return fail('LINE_NOT_FOUND');

  // Check if this is the last line
  if (invoice.lines.length === 1) return fail('NO_LINES');

  // Create new lines array without the target SKU
  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  const newInvoice = {
    ...invoice,
    lines: newLines,
  };

  return ok(newInvoice);
}

/**
 * Issue an invoice (change status from draft to issued and assign a number).
 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
 * @param {string[]} existingNumbers - Array of invoice numbers already used
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  // Check status is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Get the next invoice number
  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  const newInvoice = {
    ...invoice,
    number,
    status: 'issued',
  };

  return ok(newInvoice);
}

