  const original = JSON.stringify(invoiceResult.value);
  removeLine(invoiceResult.value, 'DEV-HOUR');
  assert.equal(JSON.stringify(invoiceResult.value), original);
});

test('removeLine returns distinct objects', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'DES-HOUR', qty: 3 },
    ],
  });

  const result1 = removeLine(invoiceResult.value, 'DEV-HOUR');
  const result2 = removeLine(invoiceResult.value, 'DEV-HOUR');

  assert.notEqual(result1.value, result2.value);
  assert.notEqual(result1.value.lines, result2.value.lines);
  assert.deepEqual(result1.value, result2.value);
});

test('addLine and removeLine work together', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  let invoice = invoiceResult.value;
  assert.equal(invoice.lines.length, 1);

  // Add a line
  let result = addLine(invoice, { sku: 'DES-HOUR', qty: 3 });
  invoice = result.value;
  assert.equal(invoice.lines.length, 2);

  // Add another line
  result = addLine(invoice, { sku: 'ICON-SET', qty: 2 });
  invoice = result.value;
  assert.equal(invoice.lines.length, 3);

  // Remove the middle line
  result = removeLine(invoice, 'DES-HOUR');
  invoice = result.value;
  assert.equal(invoice.lines.length, 2);
  assert.equal(invoice.lines[0].sku, 'DEV-HOUR');
  assert.equal(invoice.lines[1].sku, 'ICON-SET');

  // Increase qty on existing line
  result = addLine(invoice, { sku: 'DEV-HOUR', qty: 10 });
  invoice = result.value;
  assert.equal(invoice.lines.length, 2);
  assert.equal(invoice.lines[0].qty, 15);
});

