import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice } from '../src/invoices.js';

test('createInvoice returns an invoice with all required fields', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2025-10-07');
  assert.equal(result.value.status, 'draft');
  assert.equal(Array.isArray(result.value.lines), true);
});

test('createInvoice copies product details from catalogue', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(result.value.lines[0].name, 'Development (hour)');
  assert.equal(result.value.lines[0].qty, 5);
  assert.equal(result.value.lines[0].unitPrice, 9500);
  assert.equal(result.value.lines[0].vatRate, 21);
});

test('createInvoice handles multiple line items', () => {
  const result = createInvoice({
    customerId: 'C-003',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'DES-HOUR', qty: 5 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 3);
  assert.equal(result.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(result.value.lines[1].sku, 'DES-HOUR');
  assert.equal(result.value.lines[2].sku, 'LOGO-PACK');
});

test('createInvoice rejects unknown customer', () => {
  const result = createInvoice({
    customerId: 'C-999',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  });

  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice rejects invalid date format', () => {
  const formats = [
    '2025/10/07',
    '07-10-2025',
    '2025-10-7',
    '2025-1-7',
    '10-07-2025',
    '2025-13-01',
    '2025-10-32',
    'invalid',
    '',
    '2025-02-30', // invalid date
  ];

  for (const dateStr of formats) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: dateStr,
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    });
    assert.deepEqual(result, { ok: false, error: 'DATE_INVALID' }, `Failed for date: ${dateStr}`);
  }
});

test('createInvoice accepts valid dates', () => {
  const validDates = ['2025-01-01', '2025-12-31', '2000-02-29', '1999-01-01'];
  for (const dateStr of validDates) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: dateStr,
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    });
    assert.equal(result.ok, true, `Failed for valid date: ${dateStr}`);
  }
});

test('createInvoice rejects empty lines array', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [],
  });

  assert.deepEqual(result, { ok: false, error: 'NO_LINES' });
});

test('createInvoice rejects non-array lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: undefined,
  });

  assert.deepEqual(result, { ok: false, error: 'NO_LINES' });
});

test('createInvoice rejects non-integer quantity', () => {
  const invalidQties = [0, -1, 1.5, 'abc', null, undefined];

  for (const qty of invalidQties) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-10-07',
      lines: [{ sku: 'DEV-HOUR', qty }],
    });
    assert.deepEqual(result, { ok: false, error: 'QTY_INVALID' }, `Failed for qty: ${qty}`);
  }
});

test('createInvoice accepts positive integer quantities', () => {
  for (const qty of [1, 5, 100, 1000]) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-10-07',
      lines: [{ sku: 'DEV-HOUR', qty }],
    });
    assert.equal(result.ok, true, `Failed for qty: ${qty}`);
  }
});

test('createInvoice rejects unknown SKU', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'UNKNOWN-SKU', qty: 1 }],
  });

  assert.deepEqual(result, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice does not mutate input arguments', () => {
  const lines = [{ sku: 'DEV-HOUR', qty: 5 }];
  const linesCopy = JSON.stringify(lines);

  createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines,
  });

  assert.equal(JSON.stringify(lines), linesCopy);
});

test('createInvoice returns distinct objects on multiple calls', () => {
  const input = {
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  };

  const result1 = createInvoice(input);
  const result2 = createInvoice(input);

  assert.notEqual(result1.value, result2.value);
  assert.notEqual(result1.value.lines, result2.value.lines);
  assert.deepEqual(result1.value, result2.value);
});

test('lineTotal calculates qty × unitPrice', () => {
  const line = {
    sku: 'DEV-HOUR',
    name: 'Development (hour)',
    qty: 10,
    unitPrice: 9500,
    vatRate: 21,
  };

  assert.equal(lineTotal(line), 95000);
});

test('lineTotal handles single quantity', () => {
  const line = {
    sku: 'LOGO-PACK',
    name: 'Logo package',
    qty: 1,
    unitPrice: 120000,
    vatRate: 21,
  };

  assert.equal(lineTotal(line), 120000);
});

test('lineTotal rounds fractional cents', () => {
  const line = {
    sku: 'CUSTOM',
    name: 'Custom item',
    qty: 3,
    unitPrice: 100.33,
    vatRate: 21,
  };

  // 3 × 100.33 = 300.99
  assert.equal(lineTotal(line), 301);
});

test('lineTotal rounds half to even', () => {
  const line1 = {
    sku: 'CUSTOM',
    name: 'Custom item',
    qty: 2,
    unitPrice: 1.25,
    vatRate: 21,
  };

  const line2 = {
    sku: 'CUSTOM',
    name: 'Custom item',
    qty: 2,
    unitPrice: 1.75,
    vatRate: 21,
  };

  // 2 × 1.25 = 2.5, rounds to 2 (even)
  assert.equal(lineTotal(line1), 2);
  // 2 × 1.75 = 3.5, rounds to 4 (even)
  assert.equal(lineTotal(line2), 4);
});

test('invoiceTotals returns subtotal and total for single line', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const totals = invoiceTotals(result.value);
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.total, 95000);
});

test('invoiceTotals sums multiple line items', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'DES-HOUR', qty: 5 },
    ],
  });

  const totals = invoiceTotals(result.value);
  // DEV-HOUR: 10 × 9500 = 95000
  // DES-HOUR: 5 × 8500 = 42500
  // Total: 137500
  assert.equal(totals.subtotal, 137500);
  assert.equal(totals.total, 137500);
});

test('invoiceTotals sums complex line items', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 8 },
      { sku: 'DES-HOUR', qty: 3 },
      { sku: 'ICON-SET', qty: 2 },
      { sku: 'STICKER', qty: 50 },
    ],
  });

  const totals = invoiceTotals(result.value);
  // DEV-HOUR: 8 × 9500 = 76000
  // DES-HOUR: 3 × 8500 = 25500
  // ICON-SET: 2 × 980 = 1960
  // STICKER: 50 × 50 = 2500
  // Total: 105960
  assert.equal(totals.subtotal, 105960);
  assert.equal(totals.total, 105960);
});

test('invoiceTotals returns { subtotal, total } with correct structure', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const totals = invoiceTotals(result.value);
  assert.ok('subtotal' in totals);
  assert.ok('total' in totals);
  assert.equal(typeof totals.subtotal, 'number');
  assert.equal(typeof totals.total, 'number');
});

test('invoiceTotals with single expensive item', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'BRAND-BOOK', qty: 1 }],
  });

  const totals = invoiceTotals(result.value);
  // BRAND-BOOK: 1 × 245000 = 245000
  assert.equal(totals.subtotal, 245000);
  assert.equal(totals.total, 245000);
});

test('addLine adds a new line to an invoice', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const result = addLine(invoiceResult.value, { sku: 'DES-HOUR', qty: 3 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(result.value.lines[1].sku, 'DES-HOUR');
  assert.equal(result.value.lines[1].qty, 3);
  assert.equal(result.value.lines[1].name, 'Design work (hour)');
});

test('addLine increases qty if SKU already exists', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const result = addLine(invoiceResult.value, { sku: 'DEV-HOUR', qty: 3 });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 1);
  assert.equal(result.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(result.value.lines[0].qty, 8);
});

test('addLine validates qty is a positive integer', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const invalidQties = [0, -1, 1.5, 'abc'];
  for (const qty of invalidQties) {
    const result = addLine(invoiceResult.value, { sku: 'DES-HOUR', qty });
    assert.deepEqual(result, { ok: false, error: 'QTY_INVALID' }, `Failed for qty: ${qty}`);
  }
});

test('addLine validates SKU exists', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const result = addLine(invoiceResult.value, { sku: 'UNKNOWN-SKU', qty: 1 });
  assert.deepEqual(result, { ok: false, error: 'UNKNOWN_SKU' });
});

test('addLine refuses to modify non-draft invoices', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const invoice = {
    ...invoiceResult.value,
    status: 'sent',
  };

  const result = addLine(invoice, { sku: 'DES-HOUR', qty: 3 });
