211	 * Issue an invoice (change status from draft to issued and assign a number).
212	 * @param {{ customerId: string, issueDate: string, status: string, lines: Array }} invoice
213	 * @param {string[]} existingNumbers - Array of invoice numbers already used
214	 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
215	 */
216	export function issueInvoice(invoice, existingNumbers) {
217	  // Check status is draft
218	  if (invoice.status !== 'draft') return fail('NOT_DRAFT');
219	
